<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';import {AutomationError,completeAutomationOAuth,type OAuthCompletion} from './automations-client';import './automations.css';
 export let companyId='';export let providerId:string;export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher<{resumed:{companyId:string;conversationId:string;draftId:string|null};denied:{status:number};close:void}>();
 let busy=true,error='',connected=false,receipt:OAuthCompletion|null=null,generation=0;const controller=new AbortController();
 function close(){generation++;controller.abort();busy=false;receipt=null;dispatch('close');}
 onMount(()=>{const originalCompany=companyId,originalProvider=providerId,originalSignal=accessSignal,n=++generation;accessSignal.addEventListener('abort',close,{once:true});const fragments=new URLSearchParams(location.hash.slice(1));let handoff=fragments.get('handoff')||'';const valid=fragments.size===1&&fragments.getAll('handoff').length===1&&handoff.length>0&&handoff.length<=512;history.replaceState(history.state,'',location.pathname);
 if(!valid||accessSignal.aborted){error='Secure sign-in could not be verified. Return to the original setup and start authorization again.';busy=false;return;}
 const current=()=>n===generation&&!controller.signal.aborted&&!accessSignal.aborted&&companyId===originalCompany&&providerId===originalProvider&&accessSignal===originalSignal;
 void completeAutomationOAuth(providerId,{handoff},controller.signal,()=>localStorage.getItem('token')||'').then(value=>{if(!current())return;if(companyId&&value.companyId!==companyId)throw new AutomationError(0,'The connection belongs to a different company.');receipt=value;connected=true;}).catch(cause=>{if(!current())return;if(cause instanceof AutomationError&&(cause.status===401||cause.status===403))dispatch('denied',{status:cause.status});error='The sign-in result could not be confirmed. Return to the saved setup and check its connection before starting authorization again.';}).finally(()=>{handoff='';if(current())busy=false;});});
 onDestroy(()=>{generation++;controller.abort();accessSignal.removeEventListener('abort',close);receipt=null;});
</script>
<section class="starli-automations callback" aria-label="Secure integration sign-in"><span class="sa-eyebrow">STARLI INTEGRATIONS</span><h2>{connected?'Company account connected':'Completing secure sign-in'}</h2>{#if busy}<p class="sa-muted" role="status">Verifying authorization with the provider…</p>{/if}{#if error}<p class="sa-error" role="alert">{error}</p><a class="sa-link" href="/app">Return to Starli</a>{/if}{#if connected&&receipt}<p class="sa-muted">Your original conversation and saved automation setup are ready to resume.</p><button class="sa-primary" on:click={()=>receipt&&dispatch('resumed',{companyId:receipt.companyId,conversationId:receipt.conversationId,draftId:receipt.draftId})}>Return to setup</button>{/if}</section>
